// Settings: edit these before going live.
const settings = {
  company_name: 'Palm Grove Trading',
  supabase_url: 'https://YOUR-PROJECT.supabase.co',
  telegram_chat_id: 'YOUR_MANAGEMENT_CHAT_ID',
  // Haiku: three short bullets from numbers we already computed. Use claude-sonnet-5-5 for richer commentary.
  anthropic_model: 'claude-haiku-5-5',
  // Provider: anthropic | gemini. Gemini Flash-Lite is the Haiku-class option.
  llm_provider: 'anthropic',
  gemini_model: 'gemini-3.5-flash-lite',
  timezone: 'Asia/Dubai',
  anomaly_pct: 30,   // flag a channel when yesterday differs from its 7-day average by this much
};

const j = $input.first().json;
const fromWebhook = 'webhookUrl' in j;
const q = fromWebhook ? (j.query || {}) : {};
const body = fromWebhook ? (j.body || {}) : {};
const dryRun = ['1', 'true', 'yes'].includes(String(q.dry_run ?? body.dry_run ?? '').toLowerCase());

const today = DateTime.now().setZone(settings.timezone).startOf('day');
const reportDay = dryRun && body.report_date ? DateTime.fromISO(body.report_date, { zone: settings.timezone }) : today.minus({ days: 1 });
if (!reportDay.isValid) throw new Error(`invalid report_date: ${body.report_date}`);

return [{ json: {
  settings, dry_run: dryRun, source: fromWebhook ? 'webhook' : 'schedule',
  report_date: reportDay.toISODate(), start_date: reportDay.minus({ days: 7 }).toISODate(),
  sample_rows: dryRun ? (body.rows || []) : [],
} }];

function claudeRequest(model, body) {
  const fallback = !/^claude-haiku/.test(model);
  return {
    claude_body: { model, ...body, ...(fallback ? { fallbacks: 'default' } : {}) },
    claude_headers: { 'anthropic-version': '2026-10-21', ...(fallback ? { 'anthropic-beta': 'server-side-fallback-2026-07-01' } : {}) },
  };
}

// Gemini's responseSchema takes the same JSON schema minus additionalProperties.
function geminiSchema(schema) {
  if (Array.isArray(schema)) return schema.map(geminiSchema);
  if (!schema || typeof schema !== 'object') return schema;
  return Object.fromEntries(Object.entries(schema).filter(([k]) => k !== 'additionalProperties').map(([k, v]) => [k, geminiSchema(v)]));
}
function llmRequest(s, { system, user, schema, max_tokens }) {
  if (s.llm_provider === 'gemini') {
    return {
      llm_provider: 'gemini',
      gemini_url: `https://generativelanguage.googleapis.com/v1beta/models/${s.gemini_model}:generateContent`,
      gemini_body: {
        systemInstruction: { parts: [{ text: system }] },
        contents: [{ role: 'user', parts: [{ text: user }] }],
        generationConfig: { responseMimeType: 'application/json', responseSchema: geminiSchema(schema) },
      },
    };
  }
  if (s.llm_provider !== 'anthropic') throw new Error(`llm_provider must be anthropic or gemini, not "${s.llm_provider}"`);
  return {
    llm_provider: 'anthropic',
    ...claudeRequest(s.anthropic_model, {
      max_tokens, output_config: { effort: 'low', format: { type: 'json_schema', schema } }, system,
      messages: [{ role: 'user', content: user }],
    }),
  };
}

const run = $('Prepare run').first().json;
const s = run.settings;
let rows = run.sample_rows;
let fetch_error = null;
if (!run.dry_run) {
  const items = $input.all().map((i) => i.json);
  fetch_error = items.find((r) => r.error)?.error?.message || null;
  rows = items.filter((r) => r.day);
}

const num = (v) => Number(v) || 0;
const sum = (list, key) => list.reduce((a, r) => a + num(r[key]), 0);
const pct = (now, before) => (before ? Math.round(((now - before) / before) * 1000) / 10 : null);
const fmt = (n) => Math.round(n).toLocaleString('en-US');
const signed = (p) => (p === null ? 'n/a' : `${p > 0 ? '+' : ''}${p}%`);

const day = run.report_date;
const prevDay = DateTime.fromISO(day).minus({ days: 1 }).toISODate();
const week = rows.filter((r) => r.day >= run.start_date && r.day < day);
const days = new Set(week.map((r) => r.day)).size || 1;
const totals = (list) => ({ orders: sum(list, 'orders'), revenue: sum(list, 'revenue_aed'), leads: sum(list, 'new_leads') });

const y = totals(rows.filter((r) => r.day === day));
const prev = totals(rows.filter((r) => r.day === prevDay));
const avg = Object.fromEntries(Object.entries(totals(week)).map(([k, v]) => [k, v / days]));
const missing_data = !rows.some((r) => r.day === day);

const channels = [...new Set(rows.map((r) => r.channel))].sort().map((channel) => {
  const yc = totals(rows.filter((r) => r.day === day && r.channel === channel));
  const wc = totals(week.filter((r) => r.channel === channel));
  const avgRevenue = wc.revenue / days;
  return { channel, orders: yc.orders, revenue: yc.revenue, vs_avg_pct: pct(yc.revenue, avgRevenue) };
});
const anomalies = channels.filter((c) => c.vs_avg_pct !== null && Math.abs(c.vs_avg_pct) >= s.anomaly_pct);
const top = [...channels].sort((a, b) => b.revenue - a.revenue)[0];

const kpis = {
  revenue: y.revenue, orders: y.orders, new_leads: y.leads,
  avg_order_value: y.orders ? Math.round((y.revenue / y.orders) * 100) / 100 : 0,
  revenue_vs_prev_pct: pct(y.revenue, prev.revenue), revenue_vs_avg_pct: pct(y.revenue, avg.revenue),
  orders_vs_avg_pct: pct(y.orders, avg.orders), leads_vs_avg_pct: pct(y.leads, avg.leads),
};

// Every number Claude may use, written exactly as it may appear.
const facts = [
  `Revenue AED ${fmt(kpis.revenue)} (${signed(kpis.revenue_vs_prev_pct)} vs previous day, ${signed(kpis.revenue_vs_avg_pct)} vs 7-day average)`,
  `Orders ${fmt(kpis.orders)} (${signed(kpis.orders_vs_avg_pct)} vs 7-day average), average order AED ${kpis.avg_order_value.toFixed(2)}`,
  `New leads ${fmt(kpis.new_leads)} (${signed(kpis.leads_vs_avg_pct)} vs 7-day average)`,
  ...channels.map((c) => `Channel ${c.channel}: revenue AED ${fmt(c.revenue)}, ${fmt(c.orders)} orders, ${signed(c.vs_avg_pct)} vs its 7-day average`),
];

const template = missing_data ? [`No sales rows for ${day}. Check that yesterday's data was loaded.`] : [
  `Revenue was AED ${fmt(kpis.revenue)}, ${signed(kpis.revenue_vs_avg_pct)} vs the 7-day average.`,
  top ? `Top channel: ${top.channel} with AED ${fmt(top.revenue)}.` : 'No channel data.',
  anomalies.length
    ? `Unusual: ${anomalies.map((a) => `${a.channel} ${signed(a.vs_avg_pct)}`).join(', ')} vs the 7-day average.`
    : 'No channel moved more than ' + s.anomaly_pct + '% from its 7-day average.',
];

const schema = { type: 'object', additionalProperties: false, required: ['bullets'],
  properties: { bullets: { type: 'array', items: { type: 'string' }, description: 'Exactly 3 short bullet points' } } };
const request = llmRequest(s, {
  max_tokens: 2048,
  schema,
  system:
    `You write the daily sales note for the managers of ${s.company_name}. Write exactly 3 bullets of at most 20 words each: ` +
    'what changed, what stands out, what to check today. Use only the facts given and copy numbers exactly as written; ' +
    'do not compute new numbers, round, or guess causes.',
  user: `Report date: ${day}\nFacts:\n- ${facts.join('\n- ')}`,
});

return [{ json: {
  dry_run: run.dry_run, source: run.source, report_date: day, missing_data, fetch_error,
  kpis, channels, anomalies: anomalies.map((a) => a.channel), facts,
  bullets: template, commentary_source: 'template', ...request,
} }];

const BLOCKED = ['SAFETY', 'PROHIBITED_CONTENT', 'BLOCKLIST', 'SPII', 'RECITATION'];
function readLLM(res) {
  if (!res || res.error) {
    const msg = res?.error?.message || JSON.stringify(res?.error);
    // n8n replaces the API message on 429, so check the whole error (status code, description, cause).
    const limited = /429|rate.?limit|RESOURCE_EXHAUSTED|quota|spacing your requests/i.test(JSON.stringify(res?.error));
    throw new Error(`${limited ? 'rate limited (429) after retries' : 'request failed'}: ${msg}`);
  }
  if (res.candidates || res.promptFeedback) {  // Gemini generateContent
    const c = res.candidates?.[0];
    if (res.promptFeedback?.blockReason || BLOCKED.includes(c?.finishReason)) throw new Error('model declined the request');
    const text = (c?.content?.parts || []).filter((p) => p.text && !p.thought).map((p) => p.text).join('');
    if (!text) throw new Error('no text in response');
    return JSON.parse(text);
  }
  if (res.stop_reason === 'refusal') throw new Error('model declined the request');  // Claude Messages
  const text = [...(res.content || [])].reverse().find((b) => b.type === 'text')?.text;
  if (!text) throw new Error('no text block in response');
  return JSON.parse(text);
}
const PROVIDER_NAME = { anthropic: 'Claude', gemini: 'Gemini' };
const SOURCE = { anthropic: 'claude', gemini: 'gemini' };

// Guard: every number in the model's bullets must appear in the facts, otherwise keep the template.
const base = $('Compute KPIs').first().json;
const numbers = (text) => (text.match(/\d[\d,]*(?:\.\d+)?/g) || []).map((n) => n.replace(/,/g, ''));
const allowed = new Set([...numbers(base.facts.join(' ')), '7', '3']);
try {
  const bullets = readLLM($input.first().json).bullets.slice(0, 3).map((b) => String(b).trim()).filter(Boolean);
  if (!bullets.length) throw new Error('no bullets');
  const invented = bullets.flatMap(numbers).filter((n) => !allowed.has(n));
  if (invented.length) throw new Error(`numbers not in the facts: ${[...new Set(invented)].join(', ')}`);
  return [{ json: { ...base, bullets, commentary_source: SOURCE[base.llm_provider] } }];
} catch (e) {
  return [{ json: { ...base, commentary_note: `${PROVIDER_NAME[base.llm_provider]} commentary not used: ${e.message}` } }];
}

const d = $input.first().json;
const fmt = (n) => Math.round(n).toLocaleString('en-US');
const signed = (p) => (p === null ? 'n/a' : `${p > 0 ? '+' : ''}${p}%`);
const title = DateTime.fromISO(d.report_date).toFormat('cccc d LLLL yyyy');
const k = d.kpis;
const lines = d.missing_data
  ? [`Daily report, ${title}`, '', ...d.bullets.map((b) => `- ${b}`)]
  : [
      `Daily report, ${title}`,
      '',
      `Revenue: AED ${fmt(k.revenue)} (${signed(k.revenue_vs_avg_pct)} vs 7-day avg)`,
      `Orders: ${fmt(k.orders)} | Avg order: AED ${k.avg_order_value.toFixed(2)} | New leads: ${fmt(k.new_leads)}`,
      '',
      ...d.channels.map((c) => `${c.channel}: AED ${fmt(c.revenue)}, ${fmt(c.orders)} orders (${signed(c.vs_avg_pct)})`),
      '',
      ...d.bullets.map((b) => `- ${b}`),
    ];
if (d.fetch_error) lines.push('', `Data fetch error: ${d.fetch_error}`);
const { claude_body, claude_headers, ...rest } = d;
return [{ json: { ...rest, message: lines.join('\n') } }];
